NAME = "ZION CABIN 28"

class CDoc(Doc):
    def page(self, body, label="", cls="", code=""):
        n = len(self.pages) + 1
        if label and not cls.startswith("sheetpage"): self.toc.append((code or self.code, label, n))
        self.pages.append(f'<section class="page {cls}"><div class="head"><span>{zion_mark_html("14px", color="#1B2117")} {NAME} · {self.code} · {BL.REV}</span><span>{esc(code or self.code)}</span><span>{esc(label)}</span></div>{body}<div class="foot"><span>ZION GLAMPING STORE · {esc(self.title)} · SEM PREÇOS</span><span>UNIDADE: m salvo indicação · perfis em mm</span><span>{BL.DATE} · {n:02d}</span></div></section>')
    def sheet(self, name, code, title, scale="1:50"):
        self.sheet_page(f"09_CABIN/desenhos/{name}.svg", code, title, scale, NAME)

